            if not r or len(r) < 2:
                continue
            rx, ry = int(r[0]), int(r[1])
            if not valid(rx, ry):
                continue
            dm_me = md(nx, ny, rx, ry)
            dm_opp = md(ox, oy, rx, ry)
            if dm_me < my_best:
                my_best = dm_me
            if dm_opp < opp_best:
